<script>document.addEventListener('DOMContentLoaded',()=>{const b=document.querySelector('.menu-btn'),m=document.querySelector('#site-menu');if(!b||!m)return;b.addEventListener('click',()=>{const open=m.classList.toggle('open');b.setAttribute('aria-expanded',open);b.setAttribute('aria-label',open?'Close navigation menu':'Open navigation menu');b.innerHTML=open?'<i class="fa-solid fa-xmark"></i>':'<i class="fa-solid fa-bars"></i>'});m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded','false');b.setAttribute('aria-label','Open navigation menu');b.innerHTML='<i class="fa-solid fa-bars"></i>'}))});</script>
